package com.aig.feature.cad
import android.content.Context
import android.graphics.*
import android.view.MotionEvent
import android.view.View
import android.widget.*
import com.aig.core.cad.*
import com.aig.core.ui.R as UiR
import com.aig.core.ui.UiKit
import kotlin.math.*
class CadCanvasView(context:Context,private val doc:CadDocument,private val status:TextView):View(context){private val ep=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=Color.CYAN;strokeWidth=3f;style=Paint.Style.STROKE};private val sp=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=Color.MAGENTA;strokeWidth=5f;style=Paint.Style.STROKE};private val gp=Paint().apply{color=Color.rgb(15,65,78)};private val ap=Paint().apply{color=Color.rgb(0,210,235);strokeWidth=3f};private val tp=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=Color.LTGRAY;textSize=28f};private var first:PointMm?=null;private var second:PointMm?=null;private val scale=4f;init{setBackgroundColor(Color.argb(244,2,4,7))};private fun p(e:MotionEvent)=doc.snap(CadPrecision.point(((e.x-width/2f)/scale).toDouble(),((height/2f-e.y)/scale).toDouble()));private fun sx(x:Double)=width/2f+(x*scale).toFloat();private fun sy(y:Double)=height/2f-(y*scale).toFloat();override fun onTouchEvent(e:MotionEvent):Boolean{if(e.action!=MotionEvent.ACTION_UP)return true;val q=p(e);if(doc.activeTool==CadTool.SELECT){status.text=if(doc.selectNearest(q))"SELECT • ${doc.selected.size} selected" else "SELECT • no hit";invalidate();return true};if(doc.activeTool==CadTool.ARC){if(first==null){first=q;status.text="ARC P1";return true};if(second==null){second=q;status.text="ARC P2";return true};val a=arc(first!!,second!!,q);if(a!=null)doc.add(a);status.text=if(a!=null)"ARC 建立" else "ARC 三點共線";first=null;second=null;invalidate();return true};val a=first;if(a==null){first=q;status.text="${doc.activeTool} P1 X${"%.3f".format(q.x)} Y${"%.3f".format(q.y)}";return true};when(doc.activeTool){CadTool.LINE->doc.add(CadLine(a,q));CadTool.RECT->doc.add(CadRect(a,q));CadTool.CIRCLE->doc.add(CadCircle(a,hypot(q.x-a.x,q.y-a.y)));CadTool.HOLE->doc.add(CadHole(a,hypot(q.x-a.x,q.y-a.y)));else->{status.text="${doc.activeTool}：先 SELECT 幾何再執行";first=null;return true}};first=null;status.text="已建立 ${doc.activeTool} • entities=${doc.entities.size}";invalidate();return true};override fun onDraw(c:Canvas){super.onDraw(c);val ox=width/2f;val oy=height/2f;val step=80f;var x=ox%step;while(x<width){c.drawLine(x,0f,x,height.toFloat(),gp);x+=step};var y=oy%step;while(y<height){c.drawLine(0f,y,width.toFloat(),y,gp);y+=step};c.drawLine(ox,0f,ox,height.toFloat(),ap);c.drawLine(0f,oy,width.toFloat(),oy,ap);c.drawText("原點 X0.000 Y0.000",ox+10,oy-12,tp);doc.entities.forEachIndexed{i,e->val p=if(i in doc.selected)sp else ep;when(e){is CadLine->c.drawLine(sx(e.a.x),sy(e.a.y),sx(e.b.x),sy(e.b.y),p);is CadRect->c.drawRect(sx(min(e.a.x,e.b.x)),sy(max(e.a.y,e.b.y)),sx(max(e.a.x,e.b.x)),sy(min(e.a.y,e.b.y)),p);is CadCircle->c.drawCircle(sx(e.center.x),sy(e.center.y),(e.radius*scale).toFloat(),p);is CadHole->{c.drawCircle(sx(e.center.x),sy(e.center.y),(e.radius*scale).toFloat(),p);c.drawLine(sx(e.center.x)-12,sy(e.center.y),sx(e.center.x)+12,sy(e.center.y),p)};is CadArc->{val r=(e.radius*scale).toFloat();c.drawArc(RectF(sx(e.center.x)-r,sy(e.center.y)-r,sx(e.center.x)+r,sy(e.center.y)+r),(-e.startDeg).toFloat(),(-e.sweepDeg).toFloat(),false,p)};is CadPolyline->{if(e.points.isNotEmpty()){val z=Path();z.moveTo(sx(e.points[0].x),sy(e.points[0].y));e.points.drop(1).forEach{z.lineTo(sx(it.x),sy(it.y))};if(e.closed)z.close();c.drawPath(z,p)}};is CadRoundRect->{val l=sx(min(e.a.x,e.b.x));val r=sx(max(e.a.x,e.b.x));val t=sy(max(e.a.y,e.b.y));val b=sy(min(e.a.y,e.b.y));val rr=(e.radius*scale).toFloat();c.drawRoundRect(RectF(l,t,r,b),rr,rr,p)}}}};private fun arc(a:PointMm,b:PointMm,c:PointMm):CadArc?{val d=2*(a.x*(b.y-c.y)+b.x*(c.y-a.y)+c.x*(a.y-b.y));if(abs(d)<1e-9)return null;val a2=a.x*a.x+a.y*a.y;val b2=b.x*b.x+b.y*b.y;val c2=c.x*c.x+c.y*c.y;val ux=(a2*(b.y-c.y)+b2*(c.y-a.y)+c2*(a.y-b.y))/d;val uy=(a2*(c.x-b.x)+b2*(a.x-c.x)+c2*(b.x-a.x))/d;fun dg(p:PointMm)=Math.toDegrees(atan2(p.y-uy,p.x-ux));fun n(v:Double)=((v%360)+360)%360;val s=dg(a);val m=dg(b);val en=dg(c);val cc=n(en-s);val sw=if(n(m-s)<=cc)cc else cc-360;return CadArc(PointMm(ux,uy),hypot(a.x-ux,a.y-uy),s,sw)}}
object CadFeatureView{fun create(c:Context):LinearLayout{val d=CadDocument();val r=UiKit.column(c);r.addView(UiKit.skinBanner(c,UiR.drawable.aig_cad,76));val st=UiKit.statusLabel(c,"CAD READY • 0.001 mm • X0.000 Y0.000 • SNAP ON");r.addView(st);lateinit var cv:CadCanvasView;val dr=UiKit.toolGrid(c,5);listOf(CadTool.SELECT,CadTool.LINE,CadTool.RECT,CadTool.CIRCLE,CadTool.ARC,CadTool.HOLE).forEach{t->UiKit.addGridButton(dr,t.name){d.activeTool=t;st.text="CAD TOOL = ${t.name}"}};UiKit.addGridButton(dr,"UNDO"){d.undo();cv.invalidate()};UiKit.addGridButton(dr,"REDO"){d.redo();cv.invalidate()};UiKit.addGridButton(dr,"SNAP"){d.snapEnabled=!d.snapEnabled;st.text="SNAP ${if(d.snapEnabled)"ON" else "OFF"}"};UiKit.addGridButton(dr,"CLEAR SEL"){d.clearSelection();cv.invalidate()};r.addView(dr);cv=CadCanvasView(c,d,st);r.addView(cv,LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,0,1f));val e=UiKit.toolGrid(c,5);UiKit.addGridButton(e,"TRIM"){st.text=if(d.trimSelected())"TRIM 完成" else "TRIM：先 SELECT";cv.invalidate()};UiKit.addGridButton(e,"EXTEND"){st.text=if(d.extendSelected())"EXTEND 完成" else "EXTEND：先 SELECT";cv.invalidate()};UiKit.addGridButton(e,"OFFSET +5"){st.text=if(d.offsetSelected())"OFFSET 5.000 mm" else "OFFSET：先 SELECT";cv.invalidate()};UiKit.addGridButton(e,"ARRAY ×3"){st.text=if(d.arraySelected())"ARRAY ×3" else "ARRAY：先 SELECT";cv.invalidate()};UiKit.addGridButton(e,"CHAMFER"){st.text=if(d.chamferSelected())"CHAMFER 5.000" else "CHAMFER：先 SELECT RECT";cv.invalidate()};UiKit.addGridButton(e,"FILLET"){st.text=if(d.filletSelected())"FILLET R5.000" else "FILLET：先 SELECT RECT";cv.invalidate()};r.addView(e);return r}}
